import Config

# Note we also include the path to a cache manifest
# containing the digested version of static files. This
# manifest is generated by the `mix assets.deploy` task,
# which you should run after static files are built and
# before starting your production server.
config :autolaunch, AutolaunchWeb.Endpoint,
  cache_static_manifest: "priv/static/cache_manifest.json"

# Every page is served over HTTPS and says so with Strict-Transport-Security. Fly's
# proxy ends TLS and says so in `x-forwarded-proto`. Fly's health check reaches the
# machine directly over plain HTTP, so its path is answered rather than redirected.
# `:force_ssl` is read when the endpoint compiles, so it lives here.
config :autolaunch, AutolaunchWeb.Endpoint,
  force_ssl: [rewrite_on: [:x_forwarded_proto], exclude: [paths: ["/healthz"]]]

# Every request reaches production through Fly's proxy, which sets Fly-Client-IP.
config :autolaunch, :behind_fly_proxy, true

# Do not print debug messages in production
config :logger, level: :info

# The visit lines (AutolaunchWeb.VisitLog) say what each request and page did,
# by route. Phoenix's own request and connection lines would repeat them with
# each raw path and its parameters, so they are off.
config :phoenix, :logger, false

# Regent Points earning opens here with the program, at 16 November 2026 17:00
# UTC (Sean's 1 a, 15 November). The start is final: the library never lets it
# change or return to nil. These are the actions that earn; pausing one means
# taking it off this list, and each further action is added here once its
# source is built (config/config.exs names every adapter). The five account
# actions (Sean's 31 a, 19 November) are offered for what is done on this site:
# an account made at sign-in here, GitHub or Farcaster linked at sign-in, X
# connected with the Account page's X button, and an agent paired here. At
# most once a day the start run (RegentPoints.StartAwards) records what no
# offer did: this site's links and X connections, and the accounts and first
# pairings every Regent site shares, so it may record one made on another site
# that no site has recorded yet. From before the start it earns at the start,
# from after at its own time, and each earns once. A site still in read-only
# mode approves no rule at all (config/runtime.exs).
config :regent_points,
  starts_at: ~U[2026-11-16 17:00:00Z],
  approved_rules: ~w(
    autolaunch.first_launch
    autolaunch.auction_created
    autolaunch.first_graduation
    autolaunch.auction_bid
    autolaunch.token_traded
    autolaunch.token_staked
    autolaunch.first_covered_call
    account.activated
    social.x
    social.github
    social.farcaster
    agent.activated
  )

# Runtime production configuration, including reading
# of environment variables, is done on config/runtime.exs.
